import { describe, expect, it } from "vitest";
import { CallType, FlowNodeType, NodeConditionSubType } from "../types";
import { FlowStepType, type FlowStep } from "./flow-validation";
import { createFlowNodesFromFlowSteps } from "./flow-import";

function callStep(callTarget: string, options: { id?: string; mcpServer?: string } = {}): FlowStep {
  return {
    stepType: FlowStepType.Call,
    call: callTarget,
    id: options.id ?? "step-1",
    ...(options.mcpServer ? { mcpServer: options.mcpServer } : {}),
  };
}

function findCallNode(nodes: ReturnType<typeof createFlowNodesFromFlowSteps>["nodes"]) {
  return nodes.find((n) => n.type === FlowNodeType.Call);
}

describe("createFlowNodesFromFlowSteps – else-only condition (SWI-1146)", () => {
  it("does not throw when step.next starts with else (no if)", () => {
    const steps: FlowStep[] = [
      {
        action: "utter_greet",
        id: "step-greet",
        next: [{ else: [{ link: "other_flow", id: "step-link" }] }],
      },
    ];
    expect(() => createFlowNodesFromFlowSteps(steps, "test_flow")).not.toThrow();
  });

  it("produces only an Else Condition node (no If/Logic node) for an else-only next", () => {
    const steps: FlowStep[] = [
      {
        action: "utter_greet",
        id: "step-greet",
        next: [{ else: [{ link: "other_flow", id: "step-link" }] }],
      },
    ];
    const { nodes, edges } = createFlowNodesFromFlowSteps(steps, "test_flow");

    // No Logic (If...) node should be created
    const logicNode = nodes.find((n) => n.type === FlowNodeType.Logic);
    expect(logicNode).toBeUndefined();

    // An Else Condition node should exist
    const elseNode = nodes.find(
      (n) =>
        n.type === FlowNodeType.Condition &&
        (n as { subType?: NodeConditionSubType }).subType === NodeConditionSubType.ELSE,
    );
    expect(elseNode).toBeDefined();

    // The Else Condition should be wired directly from the action node (not via a Logic node)
    const actionNode = nodes.find((n) => n.label === "utter_greet");
    expect(actionNode).toBeDefined();
    const directEdge = edges.find(
      (e) => e.sourceId === actionNode!.id && e.targetId === elseNode!.id,
    );
    expect(directEdge).toBeDefined();
  });
});

describe("createFlowNodesFromFlowSteps – Call node", () => {
  describe("label", () => {
    it("uses 'Call <target>' as the label", () => {
      const { nodes } = createFlowNodesFromFlowSteps([callStep("my_agent")], "test_flow");
      expect(findCallNode(nodes)?.label).toBe("Call my_agent");
    });
  });

  describe("callType", () => {
    it("defaults to Agent when flowNamesList is not provided", () => {
      const { nodes } = createFlowNodesFromFlowSteps([callStep("some_agent")], "test_flow");
      expect(findCallNode(nodes)).toMatchObject({ callType: CallType.Agent });
    });

    it("defaults to Agent when flowNamesList is an empty array", () => {
      const { nodes } = createFlowNodesFromFlowSteps([callStep("some_agent")], "test_flow", []);
      expect(findCallNode(nodes)).toMatchObject({ callType: CallType.Agent });
    });

    it("resolves to Agent when the call target is not in flowNamesList", () => {
      const { nodes } = createFlowNodesFromFlowSteps([callStep("some_agent")], "test_flow", [
        "payment_flow",
        "booking_flow",
      ]);
      expect(findCallNode(nodes)).toMatchObject({ callType: CallType.Agent });
    });

    it("resolves to Flow when the call target matches an entry in flowNamesList", () => {
      const { nodes } = createFlowNodesFromFlowSteps([callStep("payment_flow")], "test_flow", [
        "payment_flow",
        "booking_flow",
      ]);
      expect(findCallNode(nodes)).toMatchObject({ callType: CallType.Flow });
    });

    it("resolves to Tool when mcpServer is set and call target is not a flow", () => {
      const { nodes } = createFlowNodesFromFlowSteps(
        [callStep("search_web", { mcpServer: "my_mcp_server" })],
        "test_flow",
        ["payment_flow"],
      );
      expect(findCallNode(nodes)).toMatchObject({ callType: CallType.Tool });
    });

    it("resolves to Tool when mcpServer is set and no flowNamesList", () => {
      const { nodes } = createFlowNodesFromFlowSteps(
        [callStep("search_web", { mcpServer: "my_mcp_server" })],
        "test_flow",
      );
      expect(findCallNode(nodes)).toMatchObject({ callType: CallType.Tool });
    });

    it("Flow takes precedence over mcpServer when the call target matches a flow name", () => {
      const { nodes } = createFlowNodesFromFlowSteps(
        [callStep("payment_flow", { mcpServer: "my_mcp_server" })],
        "test_flow",
        ["payment_flow"],
      );
      expect(findCallNode(nodes)).toMatchObject({ callType: CallType.Flow });
    });
  });
});
